    if (pending) {
      const continuation = normalized.trim();
      if (!continuation) {
        return pending;
      }
      const updatedValue = pending.value
        ? `${pending.value} ${continuation}`
        : continuation;
      return {
        ...pending,
        value: updatedValue,
        hasValue: pending.hasValue || continuation.length > 0,
      };
    }
    ```,Boundary detection helper added per story:
- src/rules/helpers/valid-annotation-format-internal.ts
  ```ts
  /**
   * Detect whether a normalized comment line starts with a non-traceability JSDoc tag.
   * ...
   * Related requirements:
   * - REQ-JSDOC-BOUNDARY-DETECTION
   * - REQ-JSDOC-TAG-COEXISTENCE
   */
  export function isNonTraceabilityJSDocTagLine(normalized: string): boolean {
    const trimmed = normalized.trimStart();
    if (!trimmed || !trimmed.startsWith("@")) {
      return false;
    }

    if (/^@(story|req|supports)\b/.test(trimmed)) {
      return false;
    }

    return true; // treats any other @tag as a JSDoc boundary
  }
  ```
- This matches the spec’s `/^\s*\*?\s*@\w+/` concept and recognizes any JSDoc `@*` tag except the three traceability tags, fulfilling REQ-JSDOC-BOUNDARY-DETECTION.,normalizeCommentLine supports JSDoc style and preserves tag boundaries:
- src/rules/helpers/valid-annotation-format-internal.ts
  ```ts
  export function normalizeCommentLine(rawLine: string): string {
    const trimmed = rawLine.trim();
    if (!trimmed) {
      return "";
    }

    // strip backtick-wrapped spans, preserving length
    const filtered = trimmed.replace(/`[^`]*`/g, (match) =>
      " ".repeat(match.length),
    );

    const annotationMatch = filtered.match(/@story\b|@req\b|@supports\b/);
    if (!annotationMatch || annotationMatch.index === undefined) {
      const withoutLeadingStar = filtered.replace(/^\*\s?/, "");
      return withoutLeadingStar; // JSDoc lines like "* @param" become "@param ..."
    }

    return filtered.slice(annotationMatch.index); // keeps traceability tag + value
  }
  ```
- This keeps JSDoc `*` prefixes out of the normalized text, allowing isNonTraceabilityJSDocTagLine to see lines as `@param ...`, and ensures continuation lines that don’t start with `@` are treated as part of the previous annotation (REQ-CONTINUATION-LOGIC, REQ-PRESERVE-MULTILINE).,Tests explicitly tied to this story and its requirements:
